from decimal import Decimal


def _value(record: dict | None, column: str):
    if record is None:
        return ""
    return record.get(column, "")


def _number(value) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value,
    output_column: str,
):
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            return row.get(output_column, "")

    return ""


def _error(code: str, message: str) -> dict:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001
        if event in ("INSERT", "UPDATE"):
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= 0 and discount <= 100):
                errors.append(
                    _error("E5001", "Discount out of range")
                )

        # ORD-002
        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            owner_uid = _value(record, "OWNER_UID")
            role_id = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                owner_uid,
                "ROLE_ID",
            )
            if discount > 20 and role_id != "MGR" and role_id != "ADMIN":
                errors.append(
                    _error(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003
        if event == "UPDATE":
            old_status = _value(old, "STAT_CD")
            new_status = _value(record, "STAT_CD")
            if (
                old_status == "I"
                and new_status != "I"
                and new_status != "X"
            ):
                errors.append(
                    _error(
                        "E5003",
                        "Invoiced order can only be cancelled",
                    )
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            quantity = _number(_value(record, "QTY"))
            if not quantity > 0:
                errors.append(
                    _error("E5004", "Quantity must be positive")
                )

        # ORD-005
        if event == "INSERT":
            product_id = _value(record, "PROD_ID")
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                product_id,
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(
                    _error("E5005", "Product not active")
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
